"""Tracked local Lab -> V2 -> official Sim demonstration; no network or hosted inference.

.venv/bin/python experiments/v2/run_lab_local.py --out /tmp/v2-lab-stabilization
"""

import argparse
import json
from pathlib import Path

from arena_kit.sim import Sim

from negotiator.lab.publish import load_snapshots
from negotiator.lab.runner import capture_provenance, plan_run, run_experiment
from negotiator.v2.adapters.lab import LocalV2LabAgent
from negotiator.v2.orchestration.offline import OfflineDecisionTrace

PROJECT = Path(__file__).resolve().parents[2]
DATASET = PROJECT / "experiments/v2/p10-offline-input.json"


class InProcessSimulatorClient:
    """Existing official simulator through the same client methods RecordingTable consumes."""

    def __init__(self, case):
        self.sim = Sim({case["case_id"]: case}, no_clock=False)
        self.team = "local-fixture-team"
        self.sim.teams[self.team] = "local-v2-integration"

    def cases(self, set_):
        if set_ != "practice":
            raise ValueError("local simulator supports practice-shaped fixtures only")
        return [{**c, "hosted": True} for c in self.sim.cases.values()]

    def me(self):
        return {"practice": self.sim.practice(self.team)}

    def open_session(self, case_id):
        return self.sim.open(self.team, case_id)

    def send_message(self, session_id, supplier_id, message):
        return self.sim.message(self.team, session_id, supplier_id, message)

    def session(self, session_id):
        return self.sim.state(self.team, session_id)

    def thread(self, session_id, supplier_id):
        return self.sim.thread(self.team, session_id, supplier_id)

    def attachment(self, session_id, attachment_id):
        return self.sim.attachment(self.team, session_id, attachment_id)[0]


def run_local(out, *, arms=("minimum", "direct", "grounded")):
    out = Path(out)
    dataset = json.loads(DATASET.read_text())
    provenance, _ = capture_provenance(PROJECT, data_dir=PROJECT / "tests/fixtures/v2", allow_dirty=True)
    summaries = []
    for arm in arms:
        run = plan_run(name=f"V2 local {arm}", author="local-verification",
                       hypothesis="The tracked Lab invokes the bounded V2 pipeline and retrieves genuine Sim outcomes.",
                       agent="negotiator.v2.adapters.lab:LocalV2LabAgent",
                       config={"dataset_path": str(DATASET), "trace_root": str(out / "traces"), "arm": arm},
                       cases=[dataset["case"]["case_id"]], repetitions=1, max_sessions=1,
                       environment="simulator", arena_url="http://localhost", provenance=provenance)
        final = run_experiment(run, out / "runs", InProcessSimulatorClient(dataset["case"]),
                               lambda: LocalV2LabAgent(**run.config))
        # Retrieve through the Lab's existing persisted-snapshot interface, then independently
        # verify every trace digest/certificate. Never replace simulator outcome with action validity.
        restored = next(r for _, r in load_snapshots(out / "runs") if r.run_id == final.run_id)
        attempt = restored.attempts[0]
        paths = sorted((out / "traces" / final.run_id).glob("*/decision-*.json"))
        for path in paths:
            trace = OfflineDecisionTrace.model_validate_json(path.read_bytes())
            trace.verify()
        summaries.append({"arm": arm, "run_id": final.run_id, "status": restored.status,
                          "session_id": attempt.session_id, "rounds": attempt.rounds, "score": attempt.score,
                          "deal": attempt.result.get("deal"), "end_reason": attempt.result.get("end_reason"),
                          "buyer_cost": attempt.result.get("c_deal"), "traces_verified": len(paths),
                          "metrics": attempt.result.get("agent_metrics"), "error": attempt.error})
    report = {"evidence": "local official Sim outcomes with explicitly scripted model responses",
              "hosted_calls": 0, "remote_writes": 0, "runs": summaries,
              "claim_scope": "integration/reliability only; no model superiority or semantic reliability claim"}
    out.mkdir(parents=True, exist_ok=True)
    (out / "report.json").write_text(json.dumps(report, indent=2) + "\n")
    return report


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--out", type=Path, required=True)
    args = parser.parse_args()
    report = run_local(args.out)
    print(json.dumps({"report": str(args.out / "report.json"), "runs": [
        {k: r[k] for k in ("arm", "run_id", "status", "rounds", "deal", "traces_verified", "error")}
        for r in report["runs"]]}, indent=2))
    if any(r["status"] != "completed" for r in report["runs"]):
        raise SystemExit(1)


if __name__ == "__main__":
    main()
